import torch

def run_correctness(x, negative_slope):
    output = torch.nn.functional.leaky_relu(
        x.float(), negative_slope=negative_slope
    )
    return output.to(x.dtype)


def run(x, negative_slope):
    return torch.nn.functional.leaky_relu(
        x, negative_slope=negative_slope
    )
